const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;max-height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;padding:8px;overflow:hidden;background:transparent;color:var(--ink);font-size:12px;line-height:1.35}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:6px}\n.card[data-size=\"3x6\"],.card[data-size=\"6x6\"]{padding:12px}\n.card button{font:inherit;color:var(--ink);cursor:pointer;margin:0}\n.card input,.card select{font:inherit;color:var(--ink)}\n.board,.pv{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px}\n.card[data-size=\"3x6\"] .board,.card[data-size=\"6x6\"] .board{gap:8px}\n\n/* header */\n.hdr{flex:none;display:flex;flex-direction:column;gap:6px;min-width:0}\n.hr{display:flex;align-items:center;gap:8px;min-width:0}\n.ttl{flex:1;min-width:0;display:flex;flex-direction:column}\n.ttl strong{font-size:15px;line-height:1.25}\n.sub{color:var(--muted);font-size:10.5px}\n.prog{display:flex;align-items:center;gap:8px;min-width:0}\n.pbar{flex:1;min-width:0;height:6px;border-radius:99px;background:var(--soft);overflow:hidden}\n.pfill{height:100%;background:var(--accent);border-radius:inherit}\n.ptxt{flex:none;color:var(--muted);font-size:10.5px;white-space:nowrap}\n.sel{min-width:0;max-width:100%;height:28px;padding:0 6px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:12px}\n.hr .sel{flex:none;width:112px}\n.primary{flex:none;height:28px;padding:0 12px;border:1px solid var(--accent);border-radius:8px;background:var(--accent)!important;color:var(--on-accent)!important;font-weight:600;white-space:nowrap}\n\n/* tabs */\n.tabs{flex:none;display:flex;gap:3px;align-items:stretch;min-width:0}\n.tab{flex:1;min-width:0;display:flex;align-items:center;justify-content:center;gap:2px;padding:5px 1px;border:0;border-radius:8px;background:var(--soft);color:var(--ink);font-size:11px;white-space:nowrap;overflow:hidden}\n.tab.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n.card .tab.on{color:var(--on-accent)}\n.tc{font-size:10px;opacity:.8;font-variant-numeric:tabular-nums}\n.card[data-size=\"3x6\"] .tab{padding:7px 2px;font-size:12px}\n.card .addm{flex:none;width:28px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-size:17px;line-height:1;padding:0}\n.wideadd{flex:none;height:32px;border:1px solid var(--accent);border-radius:9px;background:var(--accent)!important;color:var(--on-accent)!important;font-weight:600}\n\n/* lists */\n.list{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:5px;padding-right:1px}\n.empty{padding:14px 6px;color:var(--muted);text-align:center;font-size:11px}\n.cols{flex:1;min-height:0;min-width:0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}\n.card[data-size=\"6x6\"] .cols{gap:8px}\n.col{min-width:0;min-height:0;display:flex;flex-direction:column;gap:5px}\n.ch{flex:none;display:flex;align-items:center;gap:4px;padding:0 1px 3px;border-bottom:2px solid var(--line);font-weight:700}\n.col.st-doing .ch{border-bottom-color:var(--accent)}\n.col.st-done .ch{border-bottom-color:var(--accent-alt)}\n.cn{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.cc{flex:none;min-width:18px;padding:0 5px;border-radius:99px;background:var(--soft);font-size:10px;font-weight:600;text-align:center;line-height:1.6}\n.card .addc{flex:none;width:22px;height:20px;padding:0;border:0;border-radius:6px;background:var(--accent);color:var(--on-accent);font-size:14px;line-height:1}\n\n/* task */\n.task{flex:none;min-width:0;display:flex;flex-direction:column;gap:5px;padding:6px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.card[data-size=\"3x6\"] .task,.card[data-size=\"6x6\"] .task{padding:8px;gap:6px}\n.card .info{display:flex;flex-direction:column;gap:3px;width:100%;min-width:0;padding:0;border:0;background:none;text-align:left}\n.tt{font-size:12.5px;font-weight:600;line-height:1.3;overflow-wrap:anywhere;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden}\n.card[data-size=\"3x3\"] .tt{-webkit-line-clamp:1}\n.st-done .tt{color:var(--muted);font-weight:500;text-decoration:line-through}\n.meta{display:flex;flex-wrap:wrap;gap:3px;min-width:0}\n.chip{max-width:100%;padding:0 6px;border-radius:99px;background:var(--soft);color:var(--ink);font-size:10px;line-height:1.6;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.chip.due{background:transparent;border:1px solid var(--line);color:var(--muted);line-height:1.45}\n.chip.due.soon{background:var(--soft);border-color:var(--accent);color:var(--ink);font-weight:600}\n.chip.due.late{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.bar{display:flex;gap:4px;min-width:0}\n.card .ib{flex:1;min-width:0;height:24px;padding:0;border:1px solid var(--line);border-radius:7px;background:var(--button-paper,var(--paper));color:var(--ink);font-size:13px;line-height:1}\n.card[data-size=\"3x6\"] .ib,.card[data-size=\"6x6\"] .ib{height:26px}\n.card .ib:disabled{opacity:.3;cursor:default}\n.clr{flex:none;display:flex;gap:4px;padding:2px 0 4px}\n.card .sbtn{flex:1;min-width:0;height:24px;padding:0 4px;border:1px dashed var(--line);border-radius:7px;background:transparent;color:var(--muted);font-size:11px}\n.card .sbtn.on{border:1px solid var(--accent);background:var(--accent);color:var(--on-accent);font-weight:600}\n.err{flex:none;padding:4px 7px;border:1px solid var(--accent);border-radius:8px;background:var(--soft);color:var(--ink);font-size:11px}\n\n/* form + detail panels */\n.fh{flex:none;display:flex;align-items:center;gap:6px;min-width:0}\n.fh strong{font-size:13.5px}\n.card .back{flex:none;width:28px;height:28px;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);font-size:14px;line-height:1}\n.fb{flex:1;min-height:0;min-width:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding:1px 2px 4px 1px}\n.fb.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px 12px;align-content:start}\n.fld,.dcol{min-width:0;display:flex;flex-direction:column;gap:4px}\n.dcol{gap:8px}\n.lab{color:var(--muted);font-size:10.5px}\n.inp{width:100%;min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:13px}\n.chips{display:flex;flex-wrap:wrap;gap:4px;min-width:0}\n.card .qc{max-width:100%;height:24px;padding:0 9px;border:1px solid var(--line);border-radius:99px;background:var(--panel-paper);color:var(--ink);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card .qc.on{border-color:var(--accent);background:var(--accent);color:var(--on-accent);font-weight:600}\n.seg{display:flex;gap:3px;min-width:0}\n.card .sg{flex:1;min-width:0;height:28px;padding:0 2px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:12px;white-space:nowrap}\n.card .sg.on{border-color:var(--accent);background:var(--accent);color:var(--on-accent);font-weight:700}\n.card .sg:disabled{opacity:.35;cursor:default}\n.ff{flex:none;display:flex;gap:6px;min-width:0}\n.card .ff button{flex:1;min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font-size:12.5px}\n.card .ff .primary{flex:1;border-color:var(--accent);background:var(--accent)!important;color:var(--on-accent)!important;font-weight:700}\n.card .ff .primary:disabled{opacity:.6}\n.dt{font-size:14px;font-weight:700;line-height:1.35;overflow-wrap:anywhere}\n.kv{display:flex;align-items:baseline;gap:6px;min-width:0;font-size:12px}\n.kv .k{flex:none;width:30px;color:var(--muted);font-size:11px}\n.kv .v{flex:1;min-width:0;display:flex;flex-wrap:wrap;align-items:center;gap:4px;overflow-wrap:anywhere}\n.card[data-size=\"3x3\"] .dt{font-size:13px}\n";
var STATUS=[{k:'todo',n:'待做'},{k:'doing',n:'进行中'},{k:'done',n:'已完成'}];
var WEEKDAYS='日一二三四五六';
function pad2(n){return n<10?'0'+n:''+n;}
function dnum(s){
  var p=String(s||'').split('-').map(Number);
  if(p.length!==3||p.some(function(x){return isNaN(x);}))return NaN;
  return Math.round(Date.UTC(p[0],p[1]-1,p[2])/86400000);
}
function addDays(s,n){
  var t=new Date((dnum(s)+n)*86400000);
  return t.getUTCFullYear()+'-'+pad2(t.getUTCMonth()+1)+'-'+pad2(t.getUTCDate());
}
function dowOf(s){return new Date(dnum(s)*86400000).getUTCDay();}
function fmtMD(s){var p=String(s).split('-');return Number(p[1])+'/'+Number(p[2]);}
function fmtFull(s){var p=String(s).split('-');return Number(p[1])+'月'+Number(p[2])+'日 周'+WEEKDAYS.charAt(dowOf(s));}
function weekBounds(today){var off=(dowOf(today)+6)%7;return [addDays(today,-off),addDays(today,6-off)];}
function dueInfo(due,status,today){
  if(!due||isNaN(dnum(due)))return null;
  if(status==='done')return {text:fmtMD(due),cls:''};
  var diff=dnum(due)-dnum(today);
  if(diff<0)return {text:'逾期'+(-diff)+'天',cls:'late'};
  if(diff===0)return {text:'今天',cls:'soon'};
  if(diff===1)return {text:'明天',cls:'soon'};
  return {text:fmtMD(due),cls:''};
}
function getTasks(s){return s&&Array.isArray(s.tasks)?s.tasks:[];}
function withTasks(s,tasks){return Object.assign({},s,{tasks:tasks});}
function statusIndex(k){for(var i=0;i<STATUS.length;i++){if(STATUS[i].k===k)return i;}return 0;}
function nameOf(k){return STATUS[statusIndex(k)].n;}
function moveTo(tasks,id,st){
  var t=tasks.find(function(x){return x.id===id;});
  if(!t||t.status===st)return tasks;
  var rest=tasks.filter(function(x){return x.id!==id;});
  var nt=Object.assign({},t,{status:st});
  var idx=rest.findIndex(function(x){return x.status===st;});
  if(idx<0)rest.push(nt);else rest.splice(idx,0,nt);
  return rest;
}
function swapNeighbor(tasks,id,dir,vis){
  var i=tasks.findIndex(function(x){return x.id===id;});
  if(i<0)return tasks;
  var st=tasks[i].status;
  var j=i+dir;
  while(j>=0&&j<tasks.length&&!(tasks[j].status===st&&vis(tasks[j])))j+=dir;
  if(j<0||j>=tasks.length)return tasks;
  var c=tasks.slice();var tmp=c[i];c[i]=c[j];c[j]=tmp;
  return c;
}
function toTop(tasks,id){
  var i=tasks.findIndex(function(x){return x.id===id;});
  if(i<0)return tasks;
  var st=tasks[i].status;
  var first=tasks.findIndex(function(x){return x.status===st;});
  if(first<0||first===i)return tasks;
  var c=tasks.slice();var t=c.splice(i,1)[0];c.splice(first,0,t);
  return c;
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size}=ctx;
  const today=day();
  const tasks=getTasks(state);
  const wide=size==='6x3'||size==='6x6';
  const canFilter=size==='3x6'||size==='6x6';
  const projects=[];
  tasks.forEach(function(t){var p=String(t.project||'').trim();if(p&&projects.indexOf(p)<0)projects.push(p);});
  const filter=canFilter&&ui.filter&&projects.indexOf(ui.filter)>=0?ui.filter:'';
  const vis=function(t){return !filter||String(t.project||'').trim()===filter;};
  const tab=ui.tab||'todo';
  let mode=ui.mode||'board';
  const selTask=mode==='detail'?tasks.find(function(t){return t.id===ui.sel;}):null;
  if(mode==='detail'&&!selTask)mode='board';
  if(mode==='form'&&!ui.draft)mode='board';
  ui.scroll=ui.scroll||{};
  const restorers=[];
  let timer=null;

  function scroller(key,node){
    node.addEventListener('scroll',function(){ui.scroll[key]=node.scrollTop;});
    restorers.push(function(){node.scrollTop=ui.scroll[key]||0;});
    return node;
  }
  function fail(){ui.error='保存失败，请重试';redraw();}
  function act(fn){ui.error='';return update(fn).catch(fail);}
  function colTasks(k){return tasks.filter(function(t){return t.status===k&&vis(t);});}
  function setUi(patch){Object.assign(ui,patch);redraw();}
  function btn(cls,label,fn,opts){
    const a=Object.assign({type:'button',class:cls,onclick:fn},opts||{});
    if(!a.disabled)delete a.disabled;
    return el('button',a,...[].concat(label));
  }
  function errBar(msg){return el('div',{class:'err',role:'alert'},'⚠ '+msg);}

  function openForm(t,st,from){
    ui.scroll.form=0;
    setUi({mode:'form',formFrom:from||'board',formErr:'',error:'',saving:false,
      draft:t?{id:t.id,title:t.title,project:t.project||'',due:t.due||'',status:t.status}
             :{id:uid(),title:'',project:'',due:'',status:st||tab}});
  }
  function closeForm(){setUi({mode:ui.formFrom==='detail'?'detail':'board',draft:null,formErr:''});}
  function openDetail(id){ui.scroll.detail=0;setUi({mode:'detail',sel:id,confirmDel:false,error:''});}
  function toBoard(){setUi({mode:'board',sel:null,confirmDel:false,error:''});}
  function doMove(id,st){act(function(s){return withTasks(s,moveTo(getTasks(s),id,st));});}
  function doShift(id,dir,v){act(function(s){return withTasks(s,swapNeighbor(getTasks(s),id,dir,v||vis));});}
  function doTop(id){act(function(s){return withTasks(s,toTop(getTasks(s),id));});}

  function save(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const title=String(d.title||'').trim();
    if(!title){setUi({formErr:'请先填写任务名称'});return;}
    const rec={title:title,project:String(d.project||'').trim(),due:d.due||'',status:d.status||'todo'};
    const id=d.id;
    const back=ui.formFrom==='detail'?'detail':'board';
    ui.saving=true;ui.formErr='';
    commit(function(s){
      const ts=getTasks(s).slice();
      const i=ts.findIndex(function(x){return x.id===id;});
      if(i<0){ts.push(Object.assign({id:id},rec));return withTasks(s,ts);}
      const changed=ts[i].status!==rec.status;
      ts[i]=Object.assign({},ts[i],rec);
      return withTasks(s,changed?moveTo(ts,id,rec.status):ts);
    },Object.assign({},ui,{mode:back,sel:back==='detail'?id:null,draft:null,formErr:'',saving:false,tab:rec.status,
      filter:(filter&&rec.project!==filter)?'':ui.filter}))
    .then(function(){ui.saving=false;})
    .catch(function(){ui.saving=false;ui.formErr='保存失败，请重试';redraw();});
  }
  function doDelete(id){
    commit(function(s){return withTasks(s,getTasks(s).filter(function(x){return x.id!==id;}));},
      Object.assign({},ui,{mode:'board',sel:null,confirmDel:false,error:''})).catch(fail);
  }
  function doClear(){
    commit(function(s){return withTasks(s,getTasks(s).filter(function(x){return x.status!=='done'||!vis(x);}));},
      Object.assign({},ui,{confirmClear:false,error:''})).catch(fail);
  }


  function ibtn(label,tip,fn,dis){
    return btn('ib',label,fn,{title:tip,'aria-label':tip,disabled:!!dis});
  }
  function taskItem(t,i){
    const si=statusIndex(t.status),prev=STATUS[si-1],next=STATUS[si+1];
    const di=dueInfo(t.due,t.status,today);
    const proj=String(t.project||'').trim();
    const metaKids=[];
    if(proj)metaKids.push(el('span',{class:'chip'},proj));
    if(di)metaKids.push(el('span',{class:'chip due '+di.cls},di.text));
    const infoKids=[el('span',{class:'tt'},t.title)];
    if(metaKids.length)infoKids.push(el('span',{class:'meta'},...metaKids));
    return el('div',{class:'task st-'+t.status},
      btn('info',infoKids,function(){openDetail(t.id);},{title:'查看详情：'+t.title}),
      el('div',{class:'bar'},
        ibtn('←',prev?'移到'+prev.n:'已在第一列',function(){doMove(t.id,prev.k);},!prev),
        ibtn('↑','排前一位',function(){doShift(t.id,-1);},i===0),
        ibtn('→',next?'移到'+next.n:'已在最后一列',function(){doMove(t.id,next.k);},!next)));
  }
  function clearRow(n){
    if(ui.confirmClear){
      return el('div',{class:'clr'},
        btn('sbtn on','确认清空 '+n+' 项',doClear),
        btn('sbtn','取消',function(){setUi({confirmClear:false});}));
    }
    return el('div',{class:'clr'},btn('sbtn','清空已完成',function(){setUi({confirmClear:true});}));
  }
  function listView(k){
    const items=colTasks(k);
    const box=el('div',{class:'list'});
    if(!items.length){
      box.append(el('div',{class:'empty'},filter?'该项目下暂无任务':(k==='todo'?'还没有任务，点 + 添加':'暂无任务')));
    }
    items.forEach(function(t,i){box.append(taskItem(t,i));});
    if(k==='done'&&items.length)box.append(clearRow(items.length));
    return scroller('list-'+k,box);
  }
  function tabsRow(){
    const kids=STATUS.map(function(s){
      const on=tab===s.k;
      return el('button',{type:'button',class:'tab'+(on?' on':''),role:'tab','aria-selected':String(on),
        onclick:function(){setUi({tab:s.k,confirmClear:false});}},
        el('span',{class:'tn'},s.n),el('span',{class:'tc'},String(colTasks(s.k).length)));
    });
    if(size!=='3x6'){
      kids.push(btn('addm','+',function(){openForm(null,tab,'board');},{title:'添加任务','aria-label':'添加任务'}));
    }
    return el('div',{class:'tabs',role:'tablist'},...kids);
  }
  function columnsView(){
    return el('div',{class:'cols'},...STATUS.map(function(s){
      return el('section',{class:'col st-'+s.k},
        el('div',{class:'ch'},
          el('span',{class:'cn'},s.n),
          el('span',{class:'cc'},String(colTasks(s.k).length)),
          btn('addc','+',function(){openForm(null,s.k,'board');},{title:'添加到'+s.n,'aria-label':'添加到'+s.n})),
        listView(s.k));
    }));
  }


  function filterSelect(){
    const opts=[el('option',{value:''},'全部项目')].concat(projects.map(function(p){return el('option',{value:p},p);}));
    const sel=el('select',{class:'sel','aria-label':'按项目筛选',onchange:function(e){setUi({filter:e.target.value});}},...opts);
    sel.value=filter;
    return sel;
  }
  function headerBar(){
    const range=weekBounds(today);
    const list=tasks.filter(vis);
    const done=list.filter(function(t){return t.status==='done';}).length;
    const late=list.filter(function(t){return t.status!=='done'&&t.due&&dnum(t.due)<dnum(today);}).length;
    const pct=list.length?percent(done,list.length):0;
    const row1=[el('div',{class:'ttl'},el('strong',{},'本周任务'),el('span',{class:'sub'},fmtMD(range[0])+' – '+fmtMD(range[1])))];
    if(size==='6x6'){
      if(projects.length)row1.push(filterSelect());
      row1.push(btn('primary','+ 新任务',function(){openForm(null,'todo','board');}));
    }
    const kids=[
      el('div',{class:'hr'},...row1),
      el('div',{class:'prog'},
        el('div',{class:'pbar'},el('div',{class:'pfill',style:'width:'+pct+'%'})),
        el('span',{class:'ptxt'},'完成 '+done+'/'+list.length+(late?' · 逾期 '+late:'')))
    ];
    if(size==='3x6'&&projects.length)kids.push(filterSelect());
    return el('div',{class:'hdr'},...kids);
  }
  function boardView(){
    const kids=[];
    if(size==='3x6'||size==='6x6')kids.push(headerBar());
    if(ui.error)kids.push(errBar(ui.error));
    if(wide){
      kids.push(columnsView());
    }else{
      kids.push(tabsRow());
      kids.push(listView(tab));
      if(size==='3x6')kids.push(btn('wideadd','+ 添加任务',function(){openForm(null,tab,'board');}));
    }
    return el('div',{class:'board'},...kids);
  }


  function panelHead(title,onBack){
    return el('div',{class:'fh'},btn('back','←',onBack,{title:'返回','aria-label':'返回'}),el('strong',{},title));
  }
  function fld(label,...kids){return el('div',{class:'fld'},el('span',{class:'lab'},label),...kids);}

  function formView(){
    const d=ui.draft;
